package com.example.personalsport.data.provider

import android.content.Context

/**
 * Nano Banana Exercise Image Generator.
 *
 * Redirects all exercise image generation requests to RealisticExerciseIllustrationGenerator.
 */
object NanoBananaExerciseImageGenerator {

    const val BADGE_TEXT = RealisticExerciseIllustrationGenerator.BADGE_TEXT

    /**
     * Checks whether a given image URL string was generated by Nano Banana or Realistic Generator.
     */
    fun isNanoBananaImage(url: String?): Boolean {
        if (url.isNullOrBlank()) return false
        return url.contains("nano_banana", ignoreCase = true) ||
                RealisticExerciseIllustrationGenerator.isRealisticIllustration(url)
    }

    /**
     * Generates a realistic 3D-shaded athlete illustration for an exercise movement and exports to local cache file.
     *
     * @return Local file URL string starting with `file://`.
     */
    fun generateImageForExercise(
        context: Context?,
        exerciseName: String,
        targetMuscle: String? = null
    ): String {
        return RealisticExerciseIllustrationGenerator.generateRealisticIllustration(
            context = context,
            exerciseName = exerciseName,
            targetMuscle = targetMuscle
        )
    }

    /**
     * Generates a vector SVG string for testing or fallbacks.
     */
    fun generateSvgForExercise(exerciseName: String, targetMuscle: String? = null): String {
        val displayTitle = exerciseName.uppercase()
        val muscleName = targetMuscle ?: "GENERAL"

        return """
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 600" width="600" height="600">
                <rect width="600" height="600" fill="#FFFFFF" rx="24" stroke="#E2E8F0" stroke-width="4"/>
                <text x="300" y="50" font-family="sans-serif" font-size="24" font-weight="bold" fill="#111827" text-anchor="middle">$displayTitle</text>
                <text x="300" y="80" font-family="sans-serif" font-size="18" font-weight="bold" fill="#FF6500" text-anchor="middle">🎯 MÚSCULO: $muscleName</text>
                
                <!-- 3D Shaded Silhouette Region -->
                <ellipse cx="300" cy="240" rx="35" ry="25" fill="#FF6500" fill-opacity="0.8" stroke="#FF3D00" stroke-width="4"/>
                
                <!-- Badge -->
                <rect x="60" y="530" width="480" height="45" rx="20" fill="#1C2229" stroke="#FF6500" stroke-width="2"/>
                <text x="300" y="558" font-family="sans-serif" font-size="18" font-weight="bold" fill="#FFFFFF" text-anchor="middle">$BADGE_TEXT</text>
            </svg>
        """.trimIndent()
    }
}
